"""Generate dashboard prompt defaults from the canonical Python catalog.

Run with --check in CI to detect drift. No database or provider access.
"""

import argparse
import json
from pathlib import Path

from apex.domain.prompt_catalog import (
    APPLICATION_TEMPLATE,
    CATALOG_REVISION,
    DEFAULT_PHASE_PROMPTS,
    PLATFORM_POLICY,
)

TARGET = Path(__file__).resolve().parents[1] / "apps/dashboard/src/dev-data/telecomPrompts.ts"
POLICY_TARGET = TARGET.parent.parent / "features/prompts/platformPolicy.ts"


def render_policy() -> str:
    return (
        "// Generated by scripts/export_prompt_catalog.py; edit apex/domain/prompt_catalog.py.\n"
        + "export const PLATFORM_SYSTEM_POLICY = "
        + json.dumps(PLATFORM_POLICY, ensure_ascii=False)
        + "\n"
    )


def render() -> str:
    rows = [
        {
            "key": key,
            "description": f"APEX {key.replace('/', ' ')} instructions",
            "source": f"APEX canonical catalog {CATALOG_REVISION}",
            "content": content,
        }
        for key, content in DEFAULT_PHASE_PROMPTS.items()
    ]
    return (
        "// Generated by scripts/export_prompt_catalog.py; edit apex/domain/prompt_catalog.py.\n"
        "export interface TelecomPromptSeed {\n"
        "  key: string\n  description: string\n  source: string\n  content: string\n}\n\n"
        "export const TELECOM_PHASE_PROMPTS: TelecomPromptSeed[] = "
        + json.dumps(rows, indent=2, ensure_ascii=False)
        + "\n\n"
        "// Specializations must be explicitly wired before being advertised as active prompts.\n"
        "export const SCRIPT_VARIANT_PROMPTS: TelecomPromptSeed[] = []\n\n"
        "export const APPLICATION_PROMPT_TEMPLATE = "
        + json.dumps(APPLICATION_TEMPLATE, ensure_ascii=False)
        + "\n"
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for target, expected in ((TARGET, render()), (POLICY_TARGET, render_policy())):
        if args.check:
            if not target.exists() or target.read_text() != expected:
                raise SystemExit("Dashboard prompt catalog is stale; run export_prompt_catalog.py")
        else:
            target.write_text(expected)
